            // Should not panic, may return varying counts
            success_count += 1;
            thread::sleep(Duration::from_micros(50));
        }
        success_count
    });

    writer.join().unwrap();
    let searches = reader.join().unwrap();
    assert_eq!(searches, 100, "all searches should complete without panic");
}
