```rust
struct MockFastEmbedder {
    dimension: usize,
}

impl TwoTierEmbedder for MockFastEmbedder {
    fn embed(&self, text: &str) -> SearchResult<Vec<f32>> {
        // Deterministic embedding based on text hash
        let hash = seahash::hash(text.as_bytes());
        let mut rng = rand::rngs::SmallRng::seed_from_u64(hash);
        Ok((0..self.dimension).map(|_| rng.gen_range(-1.0..1.0)).collect())
    }

    fn dimension(&self) -> usize { self.dimension }
    fn id(&self) -> &str { "mock-fast" }
}
