    let merged = env_config.merge_with_params(Some(params));

    // Param should win
    assert!((merged.quality_weight - 0.9).abs() < 0.001);

    std::env::remove_var("TWO_TIER_QUALITY_WEIGHT");
}
```

TC16: Quality weight bounds validation
```rust
#[test]
fn test_quality_weight_bounds() {
    // Weight must be 0.0-1.0
    std::env::set_var("TWO_TIER_QUALITY_WEIGHT", "1.5");
    let config = TwoTierConfig::from_env();
    assert!(config.quality_weight <= 1.0, "weight should be clamped to 1.0");

    std::env::set_var("TWO_TIER_QUALITY_WEIGHT", "-0.5");
    let config = TwoTierConfig::from_env();
    assert!(config.quality_weight >= 0.0, "weight should be clamped to 0.0");

    std::env::remove_var("TWO_TIER_QUALITY_WEIGHT");
}
```

PROJECT ISOLATION TESTS:

TC17: Search respects project filtering
