#[test]
fn test_search_filters_by_project() {
    let config = TwoTierConfig::default();
    let mut index = TwoTierIndex::new(&config);

    // Add docs to different projects
    index.add_entry(make_entry_with_project(1, "common topic", Some(100))).unwrap();
    index.add_entry(make_entry_with_project(2, "common topic", Some(200))).unwrap();
    index.add_entry(make_entry_with_project(3, "common topic", Some(100))).unwrap();

    // Search filtered to project 100
    let results = index.search_fast_filtered(&embed("common"), 10, Some(100));

