fn test_search_includes_project_none() {
    let config = TwoTierConfig::default();
    let mut index = TwoTierIndex::new(&config);

    // Add doc with no project
    index.add_entry(make_entry_with_project(1, "orphan doc", None)).unwrap();
    // Add doc with project
    index.add_entry(make_entry_with_project(2, "orphan doc", Some(100))).unwrap();

    // Search without filter should find both
    let results = index.search_fast(&embed("orphan"), 10);
    assert_eq!(results.len(), 2);

    // Search with filter should only find project doc
    let results = index.search_fast_filtered(&embed("orphan"), 10, Some(100));
    assert_eq!(results.len(), 1);
    assert_eq!(results[0].project_id, Some(100));
